// =====================================================================
// TAB NAVIGATION + ROOT
// =====================================================================
const TABS = [
  { id: 'overview',       num: '·',    label: 'Overview' },
  { id: 'I-trend',        num: 'I',    label: 'The Curve' },
  { id: 'II-composition', num: 'II',   label: 'Composition' },
  { id: 'III-counts',     num: 'III',  label: 'Growth' },
  { id: 'IV-autism',      num: 'IV',   label: 'Autism' },
  { id: 'V-states',       num: 'V',    label: 'Geography' },
  { id: 'VI-placement',   num: 'VI',   label: 'Placement' },
  { id: 'VII-covid',      num: 'VII',  label: 'COVID' },
  { id: 'VIII-dq',        num: 'VIII', label: 'Data Quality' },
  { id: 'IX-coverage',    num: 'IX',   label: 'Coverage' },
  { id: 'X-colophon',     num: 'X',    label: 'Colophon' },
  { id: 'whitepaper',     num: '¶',    label: 'Whitepaper' },
];

function TabBar({ active, onSelect }) {
  return (
    <nav style={{
      borderTop: `1px solid ${RULE}`, borderBottom: `1px solid ${RULE}`,
      marginTop: 16, marginBottom: 8, overflowX: 'auto',
      WebkitOverflowScrolling: 'touch', position: 'sticky', top: 0,
      background: PAPER, zIndex: 10,
    }}>
      <ul style={{ listStyle:'none', padding: 0, margin: 0, display:'flex', gap: 0, whiteSpace:'nowrap' }}>
        {TABS.map(tab => {
          const isActive = active === tab.id;
          return (
            <li key={tab.id}>
              <button onClick={() => onSelect(tab.id)} style={{
                background:'transparent', border:'none',
                borderBottom: isActive ? `2px solid ${INK}` : '2px solid transparent',
                cursor:'pointer', padding:'12px 14px', fontFamily: SERIF, fontSize: 13,
                color: isActive ? INK : TEXT_3, fontWeight: 400,
                display:'flex', alignItems:'baseline', gap: 8, transition:'color 0.15s, border-color 0.15s',
              }}
              onMouseEnter={e => { if (!isActive) e.currentTarget.style.color = INK; }}
              onMouseLeave={e => { if (!isActive) e.currentTarget.style.color = TEXT_3; }}>
                <span style={{ fontFamily: MONO, fontSize: 10, color: isActive ? ACCENT : TEXT_4, letterSpacing:'0.06em' }}>
                  {tab.num}
                </span>
                <span>{tab.label}</span>
              </button>
            </li>
          );
        })}
      </ul>
    </nav>
  );
}

function Overview() {
  return (
    <React.Fragment>
      <Frontispiece />
      <AtAGlance />
    </React.Fragment>
  );
}

function ActiveSection({ active, onJump }) {
  switch (active) {
    case 'overview':       return <Overview />;
    case 'I-trend':        return <SectionI />;
    case 'II-composition': return <SectionII />;
    case 'III-counts':     return <SectionIII />;
    case 'IV-autism':      return <SectionIV />;
    case 'V-states':       return <SectionV />;
    case 'VI-placement':   return <SectionVI />;
    case 'VII-covid':      return <SectionVII />;
    case 'VIII-dq':        return <SectionVIII />;
    case 'IX-coverage':    return <SectionIX />;
    case 'X-colophon':     return <SectionX />;
    case 'whitepaper':     return <Whitepaper onJump={onJump} />;
    default:               return <Overview />;
  }
}

export default function Dashboard() {
  const [active, setActive] = useState('overview');
  React.useEffect(() => { window.scrollTo({ top: 0, behavior: 'smooth' }); }, [active]);
  return (
    <div style={{
      background: PAPER, color: INK, fontFamily: SERIF, minHeight: '100vh',
      WebkitFontSmoothing: 'antialiased', MozOsxFontSmoothing: 'grayscale',
    }}>
      <div className="px-4 sm:px-8 lg:px-16" style={{ maxWidth: 1080, margin: '0 auto', paddingBottom: 72 }}>
        <Masthead />
        <TabBar active={active} onSelect={setActive} />
        <ActiveSection active={active} onJump={setActive} />
        <SiteFooter />
      </div>
    </div>
  );
}
